/* Build Semantica: concatenate src modules into dist with an explicit
   cascade-layer order, then emit a minified copy. Zero dependencies. */
import { readFile, writeFile, mkdir } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const src = join(root, "src");
const dist = join(root, "dist");

// Order defines cascade precedence (last layer wins on equal specificity).
const LAYER_ORDER = ["reset", "tokens", "base", "layout", "components", "utilities"];

// File concatenation order (forms lives in the `base` layer, after base.css).
const FILES = [
  "reset.css",
  "tokens.css",
  "base.css",
  "forms.css",
  "layout.css",
  "components.css",
  "navigation.css",
  "overlays.css",
  "feedback.css",
  "data-display.css",
  "form-components.css",
  "media-content.css",
  "utilities.css",
];

const HEADER = `/*!
 * Semantica v0.1.0 — a semantic-HTML-first CSS library.
 * Classless base styles for native HTML + opt-in components & utilities.
 * MIT License.
 */
`;

function minify(css) {
  return css
    .replace(/\/\*[^!][\s\S]*?\*\//g, "")        // strip non-bang comments
    .replace(/\/\*![\s\S]*?\*\//g, (m) => m)       // keep /*! ... */ banner
    .replace(/\s+/g, " ")                           // collapse whitespace
    .replace(/\s*([{}:;,>])\s*/g, "$1")            // tighten around tokens
    .replace(/;}/g, "}")                            // drop trailing semicolons
    .replace(/\s*!\s*important/g, "!important")
    .trim();
}

const parts = await Promise.all(
  FILES.map((f) => readFile(join(src, f), "utf8"))
);

const layerDecl = `@layer ${LAYER_ORDER.join(", ")};\n\n`;
const bundle = HEADER + layerDecl + parts.join("\n");

await mkdir(dist, { recursive: true });
await writeFile(join(dist, "semantica.css"), bundle, "utf8");
await writeFile(join(dist, "semantica.min.css"), HEADER + minify(layerDecl + parts.join("\n")), "utf8");

const kb = (s) => (Buffer.byteLength(s, "utf8") / 1024).toFixed(1);
console.log(`✓ dist/semantica.css      ${kb(bundle)} KB`);
const min = await readFile(join(dist, "semantica.min.css"), "utf8");
console.log(`✓ dist/semantica.min.css  ${kb(min)} KB`);

