/* =========================================================================
   TOKENS — design system primitives exposed as CSS custom properties.
   Override any of these on :root (or a scope) to retheme the whole library.
   ========================================================================= */
@layer tokens {
  :root {
    /* ---- Color primitives (raw palette) -------------------------------- */
    --sui-gray-50:  #f8fafc;
    --sui-gray-100: #f1f5f9;
    --sui-gray-200: #e2e8f0;
    --sui-gray-300: #cbd5e1;
    --sui-gray-400: #94a3b8;
    --sui-gray-500: #64748b;
    --sui-gray-600: #475569;
    --sui-gray-700: #334155;
    --sui-gray-800: #1e293b;
    --sui-gray-900: #0f172a;
    --sui-gray-950: #020617;

    --sui-accent-300: #93c5fd;
    --sui-accent-400: #60a5fa;
    --sui-accent-500: #3b82f6;
    --sui-accent-600: #2563eb;
    --sui-accent-700: #1d4ed8;

    --sui-green-500: #22c55e;
    --sui-amber-500: #f59e0b;
    --sui-red-500:   #ef4444;
    --sui-red-600:   #dc2626;

    /* ---- Semantic colors (light theme defaults) ------------------------ */
    --sui-bg:            var(--sui-gray-50);
    --sui-surface:       #ffffff;
    --sui-surface-alt:   var(--sui-gray-100);
    --sui-border:        var(--sui-gray-200);
    --sui-border-strong: var(--sui-gray-300);

    --sui-text:          var(--sui-gray-900);
    --sui-text-muted:    var(--sui-gray-500);
    --sui-text-subtle:   var(--sui-gray-400);
    --sui-text-on-accent:#ffffff;

    --sui-accent:        var(--sui-accent-600);
    --sui-accent-hover:  var(--sui-accent-700);
    --sui-accent-soft:   color-mix(in srgb, var(--sui-accent-500) 12%, transparent);
    --sui-focus-ring:    color-mix(in srgb, var(--sui-accent-500) 45%, transparent);

    --sui-success: var(--sui-green-500);
    --sui-warning: var(--sui-amber-500);
    --sui-danger:  var(--sui-red-600);

    --sui-code-bg:   var(--sui-gray-100);
    --sui-code-text: var(--sui-gray-800);
    --sui-mark-bg:   #fef08a;

    /* ---- Typography ---------------------------------------------------- */
    --sui-font-sans: ui-sans-serif, system-ui, -apple-system, "Segoe UI",
                     Roboto, Helvetica, Arial, sans-serif, "Apple Color Emoji",
                     "Segoe UI Emoji";
    --sui-font-mono: ui-monospace, "SF Mono", "Cascadia Code", "JetBrains Mono",
                     "Fira Code", Consolas, "Liberation Mono", monospace;
    --sui-font-serif: ui-serif, Georgia, Cambria, "Times New Roman", serif;

    /* Fluid type scale (1.25 minor-third ratio) */
    --sui-text-xs:   clamp(0.72rem, 0.70rem + 0.10vw, 0.78rem);
    --sui-text-sm:   clamp(0.84rem, 0.81rem + 0.15vw, 0.92rem);
    --sui-text-base: clamp(1.00rem, 0.96rem + 0.20vw, 1.10rem);
    --sui-text-lg:   clamp(1.18rem, 1.10rem + 0.40vw, 1.35rem);
    --sui-text-xl:   clamp(1.45rem, 1.30rem + 0.75vw, 1.85rem);
    --sui-text-2xl:  clamp(1.85rem, 1.55rem + 1.50vw, 2.65rem);
    --sui-text-3xl:  clamp(2.30rem, 1.80rem + 2.50vw, 3.75rem);

    --sui-leading-tight:   1.2;
    --sui-leading-snug:    1.4;
    --sui-leading-normal:  1.65;
    --sui-leading-relaxed: 1.85;

    --sui-weight-normal:   400;
    --sui-weight-medium:   500;
    --sui-weight-semibold: 600;
    --sui-weight-bold:     700;

    --sui-tracking-tight: -0.02em;
    --sui-tracking-wide:  0.04em;

    /* ---- Spacing scale (rem-based, 4px step) --------------------------- */
    --sui-space-0:  0;
    --sui-space-1:  0.25rem;
    --sui-space-2:  0.5rem;
    --sui-space-3:  0.75rem;
    --sui-space-4:  1rem;
    --sui-space-5:  1.5rem;
    --sui-space-6:  2rem;
    --sui-space-7:  3rem;
    --sui-space-8:  4rem;
    --sui-space-9:  6rem;

    /* ---- Sizing -------------------------------------------------------- */
    --sui-container:    72rem;   /* max content width */
    --sui-container-sm: 48rem;   /* prose / reading width */
    --sui-measure:      66ch;    /* ideal line length for body text */

    /* ---- Radii --------------------------------------------------------- */
    --sui-radius-sm:   0.25rem;
    --sui-radius:      0.5rem;
    --sui-radius-lg:   0.75rem;
    --sui-radius-xl:   1rem;
    --sui-radius-full: 9999px;

    /* ---- Shadows ------------------------------------------------------- */
    --sui-shadow-sm: 0 1px 2px 0 rgb(15 23 42 / 0.06);
    --sui-shadow:    0 1px 3px 0 rgb(15 23 42 / 0.10), 0 1px 2px -1px rgb(15 23 42 / 0.10);
    --sui-shadow-md: 0 4px 6px -1px rgb(15 23 42 / 0.10), 0 2px 4px -2px rgb(15 23 42 / 0.08);
    --sui-shadow-lg: 0 10px 15px -3px rgb(15 23 42 / 0.12), 0 4px 6px -4px rgb(15 23 42 / 0.08);

    /* ---- Motion -------------------------------------------------------- */
    --sui-transition: 150ms cubic-bezier(0.4, 0, 0.2, 1);
    --sui-transition-slow: 300ms cubic-bezier(0.4, 0, 0.2, 1);

    /* ---- Z-index ------------------------------------------------------- */
    --sui-z-dropdown: 1000;
    --sui-z-sticky:   1020;
    --sui-z-overlay:  1040;
    --sui-z-modal:    1050;
    --sui-z-toast:    1080;

    color-scheme: light dark;
  }

  /* ---- Dark theme: automatic via OS preference ------------------------ */
  @media (prefers-color-scheme: dark) {
    :root:not([data-theme="light"]) {
      --sui-bg:            var(--sui-gray-950);
      --sui-surface:       var(--sui-gray-900);
      --sui-surface-alt:   var(--sui-gray-800);
      --sui-border:        var(--sui-gray-800);
      --sui-border-strong: var(--sui-gray-700);

      --sui-text:        var(--sui-gray-100);
      --sui-text-muted:  var(--sui-gray-400);
      --sui-text-subtle: var(--sui-gray-500);

      --sui-accent:       var(--sui-accent-500);
      --sui-accent-hover: var(--sui-accent-400);
      --sui-accent-soft:  color-mix(in srgb, var(--sui-accent-500) 18%, transparent);

      --sui-code-bg:   var(--sui-gray-800);
      --sui-code-text: var(--sui-gray-100);
      --sui-mark-bg:   #854d0e;

      --sui-shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.40);
      --sui-shadow:    0 1px 3px 0 rgb(0 0 0 / 0.50), 0 1px 2px -1px rgb(0 0 0 / 0.50);
      --sui-shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.50), 0 2px 4px -2px rgb(0 0 0 / 0.40);
      --sui-shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.55), 0 4px 6px -4px rgb(0 0 0 / 0.45);
    }
  }

  /* ---- Dark theme: explicit opt-in via [data-theme="dark"] ------------ */
  :root[data-theme="dark"] {
    --sui-bg:            var(--sui-gray-950);
    --sui-surface:       var(--sui-gray-900);
    --sui-surface-alt:   var(--sui-gray-800);
    --sui-border:        var(--sui-gray-800);
    --sui-border-strong: var(--sui-gray-700);

    --sui-text:        var(--sui-gray-100);
    --sui-text-muted:  var(--sui-gray-400);
    --sui-text-subtle: var(--sui-gray-500);

    --sui-accent:       var(--sui-accent-500);
    --sui-accent-hover: var(--sui-accent-400);
    --sui-accent-soft:  color-mix(in srgb, var(--sui-accent-500) 18%, transparent);

    --sui-code-bg:   var(--sui-gray-800);
    --sui-code-text: var(--sui-gray-100);
    --sui-mark-bg:   #854d0e;

    --sui-shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.40);
    --sui-shadow:    0 1px 3px 0 rgb(0 0 0 / 0.50), 0 1px 2px -1px rgb(0 0 0 / 0.50);
    --sui-shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.50), 0 2px 4px -2px rgb(0 0 0 / 0.40);
    --sui-shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.55), 0 4px 6px -4px rgb(0 0 0 / 0.45);
  }
}

