/* =========================================================================
   BASE — classless styling for native semantic HTML.
   Write plain, correct HTML and it looks good with no classes at all.
   ========================================================================= */
@layer base {
  /* ---- Document ------------------------------------------------------- */
  html {
    font-family: var(--sui-font-sans);
    font-size: 100%;
    scroll-behavior: smooth;
  }

  body {
    background-color: var(--sui-bg);
    color: var(--sui-text);
    font-size: var(--sui-text-base);
    transition: background-color var(--sui-transition), color var(--sui-transition);
  }

  /* A bare <body> still reads well: gentle gutter + centered measure. */
  body > header,
  body > nav,
  body > main,
  body > footer,
  body > section,
  body > article {
    padding-inline: var(--sui-space-5);
  }

  /* ---- Headings ------------------------------------------------------- */
  h1, h2, h3, h4, h5, h6 {
    line-height: var(--sui-leading-tight);
    font-weight: var(--sui-weight-bold);
    letter-spacing: var(--sui-tracking-tight);
    text-wrap: balance;
    color: var(--sui-text);
  }

  h1 { font-size: var(--sui-text-3xl); }
  h2 { font-size: var(--sui-text-2xl); }
  h3 { font-size: var(--sui-text-xl); }
  h4 { font-size: var(--sui-text-lg); }
  h5 { font-size: var(--sui-text-base); font-weight: var(--sui-weight-semibold); }
  h6 {
    font-size: var(--sui-text-sm);
    font-weight: var(--sui-weight-semibold);
    text-transform: uppercase;
    letter-spacing: var(--sui-tracking-wide);
    color: var(--sui-text-muted);
  }

  /* Vertical rhythm: space comes BEFORE block elements that follow content. */
  :is(h1, h2, h3, h4, h5, h6) + * { margin-block-start: var(--sui-space-3); }
  * + :is(h2, h3, h4, h5, h6)    { margin-block-start: var(--sui-space-6); }

  /* ---- Text ----------------------------------------------------------- */
  p {
    max-width: var(--sui-measure);
  }

  p + p,
  p + ul,
  p + ol,
  p + blockquote,
  p + pre,
  p + figure,
  p + table { margin-block-start: var(--sui-space-4); }

  small { font-size: var(--sui-text-sm); color: var(--sui-text-muted); }

  strong, b { font-weight: var(--sui-weight-semibold); }
  em, i, cite, dfn { font-style: italic; }

  mark {
    background-color: var(--sui-mark-bg);
    color: inherit;
    padding-inline: 0.2em;
    border-radius: var(--sui-radius-sm);
  }

  abbr[title] {
    text-decoration: underline dotted;
    text-underline-offset: 0.2em;
    cursor: help;
  }

  del, s { color: var(--sui-text-muted); }
  ins { text-decoration: underline; text-decoration-color: var(--sui-success); }

  sub, sup { font-size: 0.75em; line-height: 0; }

  kbd {
    font-family: var(--sui-font-mono);
    font-size: 0.85em;
    background-color: var(--sui-surface);
    color: var(--sui-text);
    border: 1px solid var(--sui-border-strong);
    border-bottom-width: 2px;
    border-radius: var(--sui-radius-sm);
    padding: 0.1em 0.4em;
    box-shadow: var(--sui-shadow-sm);
  }

  /* ---- Links ---------------------------------------------------------- */
  a {
    color: var(--sui-accent);
    text-decoration: underline;
    text-decoration-thickness: 1px;
    text-underline-offset: 0.18em;
    text-decoration-color: color-mix(in srgb, var(--sui-accent) 40%, transparent);
    transition: color var(--sui-transition), text-decoration-color var(--sui-transition);
  }

  a:hover {
    color: var(--sui-accent-hover);
    text-decoration-color: currentColor;
  }

  /* ---- Lists ---------------------------------------------------------- */
  ul, ol {
    padding-inline-start: var(--sui-space-5);
  }

  li { margin-block-start: var(--sui-space-1); }
  li::marker { color: var(--sui-text-muted); }

  /* Nested lists tuck in tighter */
  li > :is(ul, ol) { margin-block-start: var(--sui-space-1); }

  dl { display: grid; grid-template-columns: auto 1fr; gap: var(--sui-space-2) var(--sui-space-4); }
  dt { font-weight: var(--sui-weight-semibold); }
  dd { color: var(--sui-text-muted); margin: 0; }

  /* ---- Quotes --------------------------------------------------------- */
  blockquote {
    border-inline-start: 3px solid var(--sui-accent);
    padding: var(--sui-space-1) var(--sui-space-5);
    color: var(--sui-text-muted);
    font-size: var(--sui-text-lg);
    font-style: italic;
  }

  blockquote cite {
    display: block;
    margin-block-start: var(--sui-space-2);
    font-size: var(--sui-text-sm);
    font-style: normal;
    color: var(--sui-text-subtle);
  }

  blockquote cite::before { content: "— "; }

  q { quotes: "“" "”" "‘" "’"; }

  /* ---- Code ----------------------------------------------------------- */
  code, kbd, samp, pre {
    font-family: var(--sui-font-mono);
    font-size: 0.9em;
  }

  :not(pre) > code, samp {
    background-color: var(--sui-code-bg);
    color: var(--sui-code-text);
    padding: 0.15em 0.4em;
    border-radius: var(--sui-radius-sm);
    white-space: nowrap;
  }

  pre {
    background-color: var(--sui-code-bg);
    color: var(--sui-code-text);
    padding: var(--sui-space-4);
    border-radius: var(--sui-radius);
    border: 1px solid var(--sui-border);
    overflow-x: auto;
    line-height: var(--sui-leading-snug);
    tab-size: 2;
  }

  pre code {
    background: none;
    padding: 0;
    white-space: pre;
    font-size: inherit;
  }

  /* ---- Media ---------------------------------------------------------- */
  img, video {
    height: auto;
    border-radius: var(--sui-radius);
  }

  figure {
    display: flex;
    flex-direction: column;
    gap: var(--sui-space-2);
  }

  figcaption {
    font-size: var(--sui-text-sm);
    color: var(--sui-text-muted);
    text-align: center;
  }

  /* ---- Rules & separators -------------------------------------------- */
  hr {
    border: none;
    border-block-start: 1px solid var(--sui-border);
    margin-block: var(--sui-space-6);
  }

  /* ---- Tables --------------------------------------------------------- */
  table {
    width: 100%;
    border-collapse: collapse;
    font-size: var(--sui-text-sm);
    text-align: start;
  }

  caption {
    caption-side: bottom;
    padding-block-start: var(--sui-space-3);
    font-size: var(--sui-text-sm);
    color: var(--sui-text-muted);
    text-align: start;
  }

  th, td {
    padding: var(--sui-space-3) var(--sui-space-4);
    border-block-end: 1px solid var(--sui-border);
    vertical-align: top;
  }

  thead th {
    text-align: start;
    font-weight: var(--sui-weight-semibold);
    color: var(--sui-text-muted);
    border-block-end: 2px solid var(--sui-border-strong);
    white-space: nowrap;
  }

  tbody tr {
    transition: background-color var(--sui-transition);
  }
  tbody tr:hover {
    background-color: var(--sui-surface-alt);
  }

  tfoot {
    font-weight: var(--sui-weight-semibold);
  }

  /* ---- Disclosure: <details>/<summary> ------------------------------- */
  details {
    background-color: var(--sui-surface);
    border: 1px solid var(--sui-border);
    border-radius: var(--sui-radius);
    padding: var(--sui-space-3) var(--sui-space-4);
  }

  details + details { margin-block-start: var(--sui-space-2); }

  summary {
    cursor: pointer;
    font-weight: var(--sui-weight-semibold);
    list-style: none;
    display: flex;
    align-items: center;
    gap: var(--sui-space-2);
  }

  summary::-webkit-details-marker { display: none; }

  summary::before {
    content: "";
    width: 0.5em;
    height: 0.5em;
    border-right: 2px solid var(--sui-text-muted);
    border-bottom: 2px solid var(--sui-text-muted);
    transform: rotate(-45deg);
    transition: transform var(--sui-transition);
  }

  details[open] > summary::before { transform: rotate(45deg); }

  details[open] > summary { margin-block-end: var(--sui-space-3); }

  /* ---- Dialog --------------------------------------------------------- */
  dialog {
    background-color: var(--sui-surface);
    color: var(--sui-text);
    border: 1px solid var(--sui-border);
    border-radius: var(--sui-radius-lg);
    box-shadow: var(--sui-shadow-lg);
    padding: var(--sui-space-6);
    max-width: min(90vw, var(--sui-container-sm));
  }

  dialog::backdrop {
    background-color: rgb(15 23 42 / 0.45);
    backdrop-filter: blur(2px);
  }

  /* ---- Progress & meter ---------------------------------------------- */
  progress, meter {
    inline-size: 100%;
    block-size: 0.6rem;
    border: none;
    border-radius: var(--sui-radius-full);
    overflow: hidden;
    background-color: var(--sui-surface-alt);
  }
  progress::-webkit-progress-bar { background-color: var(--sui-surface-alt); }
  progress::-webkit-progress-value { background-color: var(--sui-accent); }
  progress::-moz-progress-bar { background-color: var(--sui-accent); }

  /* ---- Focus visibility (global) ------------------------------------- */
  :focus-visible {
    outline: 2px solid var(--sui-accent);
    outline-offset: 2px;
    border-radius: var(--sui-radius-sm);
  }
  :focus:not(:focus-visible) { outline: none; }

  /* ---- Selection ------------------------------------------------------ */
  ::selection {
    background-color: var(--sui-accent-soft);
    color: var(--sui-text);
  }

  /* ---- Scrollbars (subtle) ------------------------------------------- */
  * {
    scrollbar-width: thin;
    scrollbar-color: var(--sui-border-strong) transparent;
  }
}

