file.content:
/* =========================================================================
   RESET — a small, modern reset. Opinionated where it improves defaults,
   conservative everywhere else.
   ========================================================================= */
@layer reset {
  *,
  *::before,
  *::after {
    box-sizing: border-box;
  }

  * {
    margin: 0;
  }

  html {
    -webkit-text-size-adjust: 100%;
    text-size-adjust: 100%;
    tab-size: 4;
  }

  body {
    min-height: 100svh;
    line-height: var(--sui-leading-normal);
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
  }

  /* Media defaults to block + responsive */
  img,
  picture,
  video,
  canvas,
  svg {
    display: block;
    max-width: 100%;
  }

  /* Inherit fonts for form controls */
  input,
  button,
  textarea,
  select {
    font: inherit;
    color: inherit;
  }

  /* Avoid overflow from long words */
  p,
  h1, h2, h3, h4, h5, h6,
  li,
  figcaption {
    overflow-wrap: break-word;
  }

  /* Remove list styling only where the author hasn't asked for a role */
  ul[role="list"],
  ol[role="list"] {
    list-style: none;
    padding: 0;
  }

  /* Anchor target offset friendliness */
  :target {
    scroll-margin-block: var(--sui-space-6);
  }

  /* Honor reduced-motion */
  @media (prefers-reduced-motion: reduce) {
    html {
      scroll-behavior: auto;
    }
    *,
    *::before,
    *::after {
      animation-duration: 0.01ms !important;
      animation-iteration-count: 1 !important;
      transition-duration: 0.01ms !important;
      scroll-behavior: auto !important;
    }
  }
}

