16	
17	  label {
18	    display: inline-block;
19	    font-size: var(--sui-text-sm);
20	    font-weight: var(--sui-weight-medium);
21	    margin-block-end: var(--sui-space-1);
22	  }
23	
24	  /* Stack label + control + help text inside a <p> or <div> wrapper */
25	  form p,
26	  form > div {
27	    margin-block-start: var(--sui-space-4);
28	  }
29	
30	  /* ---- Text-like inputs ---------------------------------------------- */
31	  input:not([type="checkbox"]):not([type="radio"]):not([type="range"]):not([type="color"]):not([type="file"]):not([type="submit"]):not([type="reset"]):not([type="button"]),
32	  textarea,
33	  select {
34	    display: block;
