/* =========================================================================
   FORMS — classless styling for native form controls.
   ========================================================================= */
@layer base {
  fieldset {
    border: 1px solid var(--sui-border);
    border-radius: var(--sui-radius);
    padding: var(--sui-space-4) var(--sui-space-5);
  }

  legend {
    padding-inline: var(--sui-space-2);
    font-weight: var(--sui-weight-semibold);
    color: var(--sui-text);
  }

  label {
    display: inline-block;
    font-size: var(--sui-text-sm);
    font-weight: var(--sui-weight-medium);
    margin-block-end: var(--sui-space-1);
  }

  /* Stack label + control + help text inside a <p> or <div> wrapper */
  form p,
  form > div {
    margin-block-start: var(--sui-space-4);
  }

  /* ---- Text-like inputs ---------------------------------------------- */
  input:not([type="checkbox"]):not([type="radio"]):not([type="range"]):not([type="color"]):not([type="file"]):not([type="submit"]):not([type="reset"]):not([type="button"]),
  textarea,
  select {
    display: block;
    inline-size: 100%;
    padding: var(--sui-space-2) var(--sui-space-3);
    font-size: var(--sui-text-base);
    color: var(--sui-text);
    background-color: var(--sui-surface);
    border: 1px solid var(--sui-border-strong);
    border-radius: var(--sui-radius);
    transition: border-color var(--sui-transition), box-shadow var(--sui-transition);
    appearance: none;
  }

  input::placeholder,
  textarea::placeholder {
    color: var(--sui-text-subtle);
  }

  input:focus-visible,
  textarea:focus-visible,
  select:focus-visible {
    outline: none;
    border-color: var(--sui-accent);
    box-shadow: 0 0 0 3px var(--sui-focus-ring);
  }

  textarea {
    min-block-size: 6rem;
    resize: vertical;
    line-height: var(--sui-leading-snug);
  }

  /* Native select arrow */
  select:not([multiple]) {
    background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" fill="none" stroke="%2364748b" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" viewBox="0 0 24 24"><polyline points="6 9 12 15 18 9"/></svg>');
    background-repeat: no-repeat;
    background-position: right var(--sui-space-3) center;
    padding-inline-end: var(--sui-space-6);
  }

  /* ---- Checkbox & radio ---------------------------------------------- */
  input[type="checkbox"],
  input[type="radio"] {
    appearance: none;
    inline-size: 1.15em;
    block-size: 1.15em;
    margin-inline-end: var(--sui-space-1);
    vertical-align: -0.18em;
    border: 1px solid var(--sui-border-strong);
    background-color: var(--sui-surface);
    cursor: pointer;
    transition: background-color var(--sui-transition), border-color var(--sui-transition);
  }
  input[type="checkbox"] { border-radius: var(--sui-radius-sm); }
  input[type="radio"]    { border-radius: var(--sui-radius-full); }

  input[type="checkbox"]:checked,
  input[type="radio"]:checked {
    background-color: var(--sui-accent);
    border-color: var(--sui-accent);
    background-repeat: no-repeat;
    background-position: center;
  }
  input[type="checkbox"]:checked {
    background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" fill="none" stroke="white" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" viewBox="0 0 24 24"><polyline points="20 6 9 17 4 12"/></svg>');
  }
  input[type="radio"]:checked {
    background-image: radial-gradient(circle, white 38%, transparent 42%);
  }

  /* ---- Range ---------------------------------------------------------- */
  input[type="range"] {
    appearance: none;
    inline-size: 100%;
    block-size: 1.5rem;
    background: transparent;
    cursor: pointer;
  }
  input[type="range"]::-webkit-slider-runnable-track {
    block-size: 0.4rem;
    background: var(--sui-surface-alt);
    border-radius: var(--sui-radius-full);
  }
  input[type="range"]::-moz-range-track {
    block-size: 0.4rem;
    background: var(--sui-surface-alt);
    border-radius: var(--sui-radius-full);
  }
  input[type="range"]::-webkit-slider-thumb {
    appearance: none;
    margin-block-start: -0.35rem;
    inline-size: 1.1rem;
    block-size: 1.1rem;
    background: var(--sui-accent);
    border: 2px solid var(--sui-surface);
    border-radius: var(--sui-radius-full);
    box-shadow: var(--sui-shadow-sm);
  }
  input[type="range"]::-moz-range-thumb {
    inline-size: 1.1rem;
    block-size: 1.1rem;
    background: var(--sui-accent);
    border: 2px solid var(--sui-surface);
    border-radius: var(--sui-radius-full);
  }

  /* ---- File & color --------------------------------------------------- */
  input[type="file"] {
    font-size: var(--sui-text-sm);
    color: var(--sui-text-muted);
  }
  input[type="file"]::file-selector-button {
    margin-inline-end: var(--sui-space-3);
    padding: var(--sui-space-2) var(--sui-space-3);
    font-weight: var(--sui-weight-medium);
    color: var(--sui-text);
    background-color: var(--sui-surface-alt);
    border: 1px solid var(--sui-border-strong);
    border-radius: var(--sui-radius);
    cursor: pointer;
    transition: background-color var(--sui-transition);
  }
  input[type="file"]::file-selector-button:hover {
    background-color: var(--sui-border);
  }

  input[type="color"] {
    inline-size: 3rem;
    block-size: 2.5rem;
    padding: 0.2rem;
    border: 1px solid var(--sui-border-strong);
    border-radius: var(--sui-radius);
    background-color: var(--sui-surface);
    cursor: pointer;
  }

  /* ---- Buttons (native) ---------------------------------------------- */
  button,
  input[type="submit"],
  input[type="reset"],
  input[type="button"] {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--sui-space-2);
    padding: var(--sui-space-2) var(--sui-space-5);
    font-size: var(--sui-text-base);
    font-weight: var(--sui-weight-medium);
    line-height: 1.2;
    color: var(--sui-text-on-accent);
    background-color: var(--sui-accent);
    border: 1px solid transparent;
    border-radius: var(--sui-radius);
    cursor: pointer;
    text-decoration: none;
    transition: background-color var(--sui-transition), transform var(--sui-transition),
                box-shadow var(--sui-transition);
    user-select: none;
  }

  button:hover,
  input[type="submit"]:hover,
  input[type="reset"]:hover,
  input[type="button"]:hover {
    background-color: var(--sui-accent-hover);
  }

  button:active,
  input[type="submit"]:active,
  input[type="reset"]:active,
  input[type="button"]:active {
    transform: translateY(1px);
  }

  /* Secondary tone for reset buttons by default */
  input[type="reset"],
  button[type="reset"] {
    color: var(--sui-text);
    background-color: var(--sui-surface-alt);
    border-color: var(--sui-border-strong);
  }
  input[type="reset"]:hover,
  button[type="reset"]:hover {
    background-color: var(--sui-border);
  }

  /* ---- Disabled & invalid -------------------------------------------- */
  :disabled,
  [aria-disabled="true"] {
    opacity: 0.55;
    cursor: not-allowed;
    pointer-events: none;
  }

  input:user-invalid,
  textarea:user-invalid,
  select:user-invalid {
    border-color: var(--sui-danger);
  }
  input:user-invalid:focus-visible,
  textarea:user-invalid:focus-visible,
  select:user-invalid:focus-visible {
    box-shadow: 0 0 0 3px color-mix(in srgb, var(--sui-danger) 30%, transparent);
  }

  /* Help text immediately following a control */
  input + small,
  textarea + small,
  select + small {
    display: block;
    margin-block-start: var(--sui-space-1);
  }
}

