1	/* =========================================================================
2	   COMPONENTS — opt-in classes layered on top of semantic markup.
3	   Use these when native HTML has no element for the pattern.
4	   ========================================================================= */
5	@layer components {
6	  /* ---- Buttons: variants & sizes ------------------------------------- */
7	  /* `.button` makes a non-button element (usually <a>) look like one. */
8	  .button {
9	    display: inline-flex;
10	    align-items: center;
11	    justify-content: center;
12	    gap: var(--sui-space-2);
13	    padding: var(--sui-space-2) var(--sui-space-5);
14	    font-size: var(--sui-text-base);
15	    font-weight: var(--sui-weight-medium);
16	    line-height: 1.2;
17	    color: var(--sui-text-on-accent);
18	    background-color: var(--sui-accent);
19	    border: 1px solid transparent;
20	    border-radius: var(--sui-radius);
21	    text-decoration: none;
22	    cursor: pointer;
23	    user-select: none;
24	    transition: background-color var(--sui-transition), transform var(--sui-transition);
25	  }
26	  .button:hover { background-color: var(--sui-accent-hover); color: var(--sui-text-on-accent); }
27	  .button:active { transform: translateY(1px); }
28	
29	  /* Variants apply to native <button>, <input> buttons, and .button alike */
30	  :is(button, .button, input[type="submit"], input[type="button"])[data-variant="secondary"] {
31	    color: var(--sui-text);
32	    background-color: var(--sui-surface-alt);
33	    border-color: var(--sui-border-strong);
34	  }
35	  :is(button, .button, input[type="submit"], input[type="button"])[data-variant="secondary"]:hover {
36	    background-color: var(--sui-border);
37	    color: var(--sui-text);
38	  }
39	
40	  :is(button, .button)[data-variant="outline"] {
41	    color: var(--sui-accent);
42	    background-color: transparent;
43	    border-color: currentColor;
44	  }
45	  :is(button, .button)[data-variant="outline"]:hover {
46	    background-color: var(--sui-accent-soft);
47	    color: var(--sui-accent-hover);
48	  }
49	
50	  :is(button, .button)[data-variant="ghost"] {
51	    color: var(--sui-text);
52	    background-color: transparent;
53	  }
54	  :is(button, .button)[data-variant="ghost"]:hover {
55	    background-color: var(--sui-surface-alt);
56	  }
57	
58	  :is(button, .button)[data-variant="danger"]  { background-color: var(--sui-danger); }
59	  :is(button, .button)[data-variant="danger"]:hover  { background-color: var(--sui-red-600); filter: brightness(0.92); }
60	  :is(button, .button)[data-variant="success"] { background-color: var(--sui-success); }
61	  :is(button, .button)[data-variant="success"]:hover { filter: brightness(0.92); }
62	
63	  :is(button, .button)[data-size="sm"] {
64	    padding: var(--sui-space-1) var(--sui-space-3);
65	    font-size: var(--sui-text-sm);
66	  }
67	  :is(button, .button)[data-size="lg"] {
68	    padding: var(--sui-space-3) var(--sui-space-6);
69	    font-size: var(--sui-text-lg);
70	  }
71	  :is(button, .button)[data-block] { display: flex; inline-size: 100%; }
72	
73	  /* Button group: joined segmented buttons */
74	  .button-group {
75	    display: inline-flex;
76	    border-radius: var(--sui-radius);
77	    box-shadow: var(--sui-shadow-sm);
78	  }
79	  .button-group > :is(button, .button) {
80	    border-radius: 0;
81	    box-shadow: none;
82	  }
83	  .button-group > :is(button, .button):first-child {
84	    border-start-start-radius: var(--sui-radius);
85	    border-end-start-radius: var(--sui-radius);
86	  }
87	  .button-group > :is(button, .button):last-child {
88	    border-start-end-radius: var(--sui-radius);
89	    border-end-end-radius: var(--sui-radius);
90	  }
91	  .button-group > :is(button, .button):not(:first-child) {
92	    border-inline-start: 1px solid rgb(255 255 255 / 0.2);
93	  }
94	
95	  /* ---- Card ----------------------------------------------------------- */
96	  .card {
97	    display: flex;
98	    flex-direction: column;
99	    gap: var(--sui-space-3);
100	    background-color: var(--sui-surface);
101	    border: 1px solid var(--sui-border);
102	    border-radius: var(--sui-radius-lg);
103	    padding: var(--sui-space-5);
104	    box-shadow: var(--sui-shadow-sm);
105	    transition: box-shadow var(--sui-transition), border-color var(--sui-transition),
106	                transform var(--sui-transition);
107	  }
108	  .card > :is(h1, h2, h3, h4, h5, h6) { margin: 0; }
109	  .card > p { margin: 0; max-width: none; }
110	
111	  /* Interactive cards (links / [data-interactive]) lift on hover */
112	  a.card,
113	  .card[data-interactive] {
114	    text-decoration: none;
115	    color: inherit;
116	  }
117	  a.card:hover,
118	  .card[data-interactive]:hover {
119	    border-color: var(--sui-border-strong);
120	    box-shadow: var(--sui-shadow-md);
121	    transform: translateY(-2px);
122	  }
123	
124	  /* Edge-to-edge media inside a card */
125	  .card > :is(img, video):first-child {
126	    margin: calc(-1 * var(--sui-space-5)) calc(-1 * var(--sui-space-5)) 0;
