/* =========================================================================
   COMPONENTS — opt-in classes layered on top of semantic markup.
   Use these when native HTML has no element for the pattern.
   ========================================================================= */
@layer components {
  /* ---- Buttons: variants & sizes ------------------------------------- */
  /* `.button` makes a non-button element (usually <a>) look like one. */
  .button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--sui-space-2);
    padding: var(--sui-space-2) var(--sui-space-5);
    font-size: var(--sui-text-base);
    font-weight: var(--sui-weight-medium);
    line-height: 1.2;
    color: var(--sui-text-on-accent);
    background-color: var(--sui-accent);
    border: 1px solid transparent;
    border-radius: var(--sui-radius);
    text-decoration: none;
    cursor: pointer;
    user-select: none;
    transition: background-color var(--sui-transition), transform var(--sui-transition);
  }
  .button:hover { background-color: var(--sui-accent-hover); color: var(--sui-text-on-accent); }
  .button:active { transform: translateY(1px); }

  /* Variants apply to native <button>, <input> buttons, and .button alike */
  :is(button, .button, input[type="submit"], input[type="button"])[data-variant="secondary"] {
    color: var(--sui-text);
    background-color: var(--sui-surface-alt);
    border-color: var(--sui-border-strong);
  }
  :is(button, .button, input[type="submit"], input[type="button"])[data-variant="secondary"]:hover {
    background-color: var(--sui-border);
    color: var(--sui-text);
  }

  :is(button, .button)[data-variant="outline"] {
    color: var(--sui-accent);
    background-color: transparent;
    border-color: currentColor;
  }
  :is(button, .button)[data-variant="outline"]:hover {
    background-color: var(--sui-accent-soft);
    color: var(--sui-accent-hover);
  }

  :is(button, .button)[data-variant="ghost"] {
    color: var(--sui-text);
    background-color: transparent;
  }
  :is(button, .button)[data-variant="ghost"]:hover {
    background-color: var(--sui-surface-alt);
  }

  :is(button, .button)[data-variant="danger"]  { background-color: var(--sui-danger); }
  :is(button, .button)[data-variant="danger"]:hover  { background-color: var(--sui-red-600); filter: brightness(0.92); }
  :is(button, .button)[data-variant="success"] { background-color: var(--sui-success); }
  :is(button, .button)[data-variant="success"]:hover { filter: brightness(0.92); }

  :is(button, .button)[data-size="sm"] {
    padding: var(--sui-space-1) var(--sui-space-3);
    font-size: var(--sui-text-sm);
  }
  :is(button, .button)[data-size="lg"] {
    padding: var(--sui-space-3) var(--sui-space-6);
    font-size: var(--sui-text-lg);
  }
  :is(button, .button)[data-block] { display: flex; inline-size: 100%; }

  /* Button group: joined segmented buttons */
  .button-group {
    display: inline-flex;
    border-radius: var(--sui-radius);
    box-shadow: var(--sui-shadow-sm);
  }
  .button-group > :is(button, .button) {
    border-radius: 0;
    box-shadow: none;
  }
  .button-group > :is(button, .button):first-child {
    border-start-start-radius: var(--sui-radius);
    border-end-start-radius: var(--sui-radius);
  }
  .button-group > :is(button, .button):last-child {
    border-start-end-radius: var(--sui-radius);
    border-end-end-radius: var(--sui-radius);
  }
  .button-group > :is(button, .button):not(:first-child) {
    border-inline-start: 1px solid rgb(255 255 255 / 0.2);
  }

  /* ---- Card ----------------------------------------------------------- */
  .card {
    display: flex;
    flex-direction: column;
    gap: var(--sui-space-3);
    background-color: var(--sui-surface);
    border: 1px solid var(--sui-border);
    border-radius: var(--sui-radius-lg);
    padding: var(--sui-space-5);
    box-shadow: var(--sui-shadow-sm);
    transition: box-shadow var(--sui-transition), border-color var(--sui-transition),
                transform var(--sui-transition);
  }
  .card > :is(h1, h2, h3, h4, h5, h6) { margin: 0; }
  .card > p { margin: 0; max-width: none; }

  /* Interactive cards (links / [data-interactive]) lift on hover */
  a.card,
  .card[data-interactive] {
    text-decoration: none;
    color: inherit;
  }
  a.card:hover,
  .card[data-interactive]:hover {
    border-color: var(--sui-border-strong);
    box-shadow: var(--sui-shadow-md);
    transform: translateY(-2px);
  }

  /* Edge-to-edge media inside a card */
  .card > :is(img, video):first-child {
    margin: calc(-1 * var(--sui-space-5)) calc(-1 * var(--sui-space-5)) 0;
    max-inline-size: calc(100% + 2 * var(--sui-space-5));
    inline-size: calc(100% + 2 * var(--sui-space-5));
    border-radius: var(--sui-radius-lg) var(--sui-radius-lg) 0 0;
  }

  .card > footer {
    margin-block-start: auto;
    padding-block-start: var(--sui-space-3);
    border-block-start: 1px solid var(--sui-border);
    color: var(--sui-text-muted);
    font-size: var(--sui-text-sm);
  }

  /* ---- Badge / tag / pill -------------------------------------------- */
  .badge {
    display: inline-flex;
    align-items: center;
    gap: var(--sui-space-1);
    padding: 0.15em 0.6em;
    font-size: var(--sui-text-xs);
    font-weight: var(--sui-weight-semibold);
    line-height: 1.4;
    border-radius: var(--sui-radius-full);
    background-color: var(--sui-surface-alt);
    color: var(--sui-text-muted);
    white-space: nowrap;
  }
  .badge[data-variant="accent"]  { background-color: var(--sui-accent-soft); color: var(--sui-accent); }
  .badge[data-variant="success"] { background-color: color-mix(in srgb, var(--sui-success) 16%, transparent); color: var(--sui-success); }
  .badge[data-variant="warning"] { background-color: color-mix(in srgb, var(--sui-warning) 18%, transparent); color: var(--sui-amber-500); }
  .badge[data-variant="danger"]  { background-color: color-mix(in srgb, var(--sui-danger) 14%, transparent); color: var(--sui-danger); }
  .badge[data-variant="solid"]   { background-color: var(--sui-accent); color: var(--sui-text-on-accent); }

  /* Status dot */
  .badge[data-dot]::before {
    content: "";
    inline-size: 0.5em;
    block-size: 0.5em;
    border-radius: var(--sui-radius-full);
    background-color: currentColor;
  }

  /* ---- Callout / alert ----------------------------------------------- */
  /* Use on <aside>, <div>, or role="alert"/"status" elements. */
  .callout,
  [role="alert"],
  [role="status"] {
    display: flex;
    gap: var(--sui-space-3);
    padding: var(--sui-space-4);
    border: 1px solid var(--sui-border);
    border-inline-start: 4px solid var(--sui-text-muted);
    border-radius: var(--sui-radius);
    background-color: var(--sui-surface);
    color: var(--sui-text);
  }
  .callout > :last-child { margin-block-end: 0; }
  .callout strong:first-child { display: block; }

  .callout[data-variant="info"],
  [role="status"] {
    border-inline-start-color: var(--sui-accent);
    background-color: var(--sui-accent-soft);
  }
  .callout[data-variant="success"] {
    border-inline-start-color: var(--sui-success);
    background-color: color-mix(in srgb, var(--sui-success) 10%, transparent);
  }
  .callout[data-variant="warning"] {
    border-inline-start-color: var(--sui-warning);
    background-color: color-mix(in srgb, var(--sui-warning) 12%, transparent);
  }
  .callout[data-variant="danger"],
  [role="alert"] {
    border-inline-start-color: var(--sui-danger);
    background-color: color-mix(in srgb, var(--sui-danger) 9%, transparent);
  }

  /* ---- Tabs (ARIA-driven, JS toggles aria-selected/hidden) ----------- */
  [role="tablist"] {
    display: flex;
    flex-wrap: wrap;
    gap: var(--sui-space-1);
    border-block-end: 1px solid var(--sui-border);
  }
  [role="tab"] {
    appearance: none;
    background: none;
    border: none;
    border-block-end: 2px solid transparent;
    margin-block-end: -1px;
    padding: var(--sui-space-2) var(--sui-space-4);
    color: var(--sui-text-muted);
    font-weight: var(--sui-weight-medium);

content.content:
  .text-accent  { color: var(--sui-accent); }
  .text-sm      { font-size: var(--sui-text-sm); }
  .text-lg      { font-size: var(--sui-text-lg); }
  .uppercase    { text-transform: uppercase; letter-spacing: var(--sui-tracking-wide); }
  .font-mono    { font-family: var(--sui-font-mono); }
  .font-bold    { font-weight: var(--sui-weight-bold); }
  .font-normal  { font-weight: var(--sui-weight-normal); }

  /* Truncate to one line */
  .truncate {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  /* Clamp to N lines via --lines */
  .line-clamp {
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: var(--lines, 3);
    line-clamp: var(--lines, 3);
    overflow: hidden;
  }

  /* ---- Spacing (margin / padding shorthands) ------------------------- */
  .mt-0 { margin-block-start: 0; }
  .mt-2 { margin-block-start: var(--sui-space-2); }
